import{_ as h,C as i,o as E,c as d,a5 as s,E as r,j as a,a as t,b as c,w as l,a6 as B}from"./chunks/framework.D_J2JZBr.js";const _=JSON.parse('{"title":"EDA 与可制造性设计","description":"从 EE215A、SI365 到 AI4EDA，认识上科大的设计自动化、物理设计与计算光刻研究。","frontmatter":{"title":"EDA 与可制造性设计","description":"从 EE215A、SI365 到 AI4EDA，认识上科大的设计自动化、物理设计与计算光刻研究。"},"headers":[],"relativePath":"explore-ic/research-directions/eda.md","filePath":"explore-ic/research-directions/eda.md","lastUpdated":1795531638000}'),u={name:"explore-ic/research-directions/eda.md"};function D(p,e,f,m,g,b){const n=i("FacultyList"),o=i("CourseTable"),A=i("Mermaid");return E(),d("div",null,[e[1]||(e[1]=s('<h1 id="eda-与可制造性设计" tabindex="-1">EDA 与可制造性设计 <a class="header-anchor" href="#eda-与可制造性设计" aria-label="Permalink to &quot;EDA 与可制造性设计&quot;">​</a></h1><h2 id="这个方向在做什么" tabindex="-1">这个方向在做什么 <a class="header-anchor" href="#这个方向在做什么" aria-label="Permalink to &quot;这个方向在做什么&quot;">​</a></h2><p>电子设计自动化（Electronic Design Automation，EDA）把电路设计中的复杂任务转化为算法、模型与工程软件，覆盖综合、验证、布局布线、仿真和签核等环节。可制造性设计（Design for Manufacturability，DFM）则关心版图在真实制造条件下能否可靠实现。AI4EDA 是用人工智能辅助这些任务，不等同于“设计 AI 芯片”，也不意味着可以绕过物理与工艺约束。</p><p>核心研究问题包括：</p><ul><li>如何把逻辑、电路与版图需求表述为可求解的优化问题？</li><li>芯片设计空间探索（DSE）怎样平衡评估代价、搜索效率与结果质量？</li><li>布局布线怎样同时满足时序、拥塞、功耗与设计规则？</li><li>计算光刻、掩模优化和热点检测怎样连接设计与制造？</li><li>学习模型能否泛化到新的设计、工艺或工具配置？</li><li>怎样保证优化结果可验证、可复现，并能接入完整设计流程？</li></ul><h2 id="上科大谁在做" tabindex="-1">上科大谁在做 <a class="header-anchor" href="#上科大谁在做" aria-label="Permalink to &quot;上科大谁在做&quot;">​</a></h2><p>上科大公开方向包含算法、物理实现与制造接口。耿浩关注机器学习赋能 EDA，重点包括芯片设计空间探索、可制造性设计与计算光刻；中心介绍材料给出的例子包括加法器设计探索、EDA 工具参数调整、掩模优化和版图热点检测。张芯韵关注 AI 驱动的芯片设计自动化、IC 可制造性设计与物理设计，是 AI4EDA 的另一公开研究入口。</p><p>周平强的集成电路与系统实验室涉及 EDA、集成电路设计、硬件安全与光电混合计算；任轩乐关注芯片设计自动化、隐私计算芯片与硬件安全；吴涛的公开方向包含 AI 辅助集成电路设计（AI4IC）。方向存在交叉，但具体任务、数据和工具链不同，不能把一个模型在某个公开数据集上的表现泛化到整条芯片设计流程。</p>',8)),r(n,{dir:"eda"}),e[2]||(e[2]=a("h2",{id:"相关上科大课程",tabindex:"-1"},[t("相关上科大课程 "),a("a",{class:"header-anchor",href:"#相关上科大课程","aria-label":'Permalink to "相关上科大课程"'},"​")],-1)),e[3]||(e[3]=a("p",null,"EE215A 集成电路设计自动化是算法与设计问题的直接入口，SI365 人工智能赋能集成电路设计制造则对应 AI 与 IC 设计制造的交叉；同时需要数字实现、数据结构和优化基础。",-1)),r(o,{codes:"CS100,EE113,EE215A,SI365,SI231B,SI251,EE291F,EE2210,CS280"}),e[4]||(e[4]=a("p",null,[a("a",{href:"/shanghaitech-ic-wiki-dev.github.io/shanghaitech/courses/ee291f"},"EE291F 数字 VLSI 设计流程"),t(" 有助于认识工具之间的关系。课程名称与计划先修仅提供选课线索，实际讲授范围、选课资格和开课情况以当学期公布为准。")],-1)),e[5]||(e[5]=a("h2",{id:"知识前置",tabindex:"-1"},[t("知识前置 "),a("a",{class:"header-anchor",href:"#知识前置","aria-label":'Permalink to "知识前置"'},"​")],-1)),e[6]||(e[6]=a("p",null,"下图是建议学习路线，不代替教务先修要求；算法线与芯片实现线应交叉推进。",-1)),(E(),c(B,null,{default:l(()=>[r(A,{id:"mermaid-72",class:"mermaid",graph:"graph%20LR%0A%20%20A%5B%22CS100%20%E8%AE%A1%E7%AE%97%E6%9C%BA%E7%BC%96%E7%A8%8B%22%5D%20--%3E%20B%5B%22%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%22%5D%0A%20%20C%5B%22%E7%BA%BF%E6%80%A7%E4%BB%A3%E6%95%B0%E4%B8%8E%E6%95%B0%E5%AD%A6%E5%88%86%E6%9E%90%22%5D%20--%3E%20D%5B%22SI231B%20%E7%9F%A9%E9%98%B5%E8%AE%A1%E7%AE%97%22%5D%0A%20%20C%20--%3E%20E%5B%22SI251%20%E5%87%B8%E4%BC%98%E5%8C%96%22%5D%0A%20%20F%5B%22EE115B%20%E6%95%B0%E5%AD%97%E7%94%B5%E8%B7%AF%22%5D%20--%3E%20G%5B%22EE113%20%E6%95%B0%E5%AD%97%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AFI%22%5D%0A%20%20G%20--%3E%20H%5B%22EE291F%20%E6%95%B0%E5%AD%97VLSI%E8%AE%BE%E8%AE%A1%E6%B5%81%E7%A8%8B%22%5D%0A%20%20B%20--%3E%20I%5B%22EE215A%20%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AF%E8%AE%BE%E8%AE%A1%E8%87%AA%E5%8A%A8%E5%8C%96%22%5D%0A%20%20G%20--%3E%20I%0A%20%20D%20--%3E%20I%0A%20%20E%20--%3E%20I%0A%20%20J%5B%22%E6%9C%BA%E5%99%A8%E5%AD%A6%E4%B9%A0%E5%9F%BA%E7%A1%80%22%5D%20--%3E%20K%5B%22CS280%20%E6%B7%B1%E5%BA%A6%E5%AD%A6%E4%B9%A0%22%5D%0A%20%20K%20--%3E%20L%5B%22SI365%20%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD%E8%B5%8B%E8%83%BD%E9%9B%86%E6%88%90%E7%94%B5%E8%B7%AF%E8%AE%BE%E8%AE%A1%E5%88%B6%E9%80%A0%22%5D%0A%20%20F%20--%3E%20L%0A%20%20H%20--%3E%20M%5B%22EDA%20%E4%B8%8E%20AI4EDA%20%E7%A0%94%E7%A9%B6%22%5D%0A%20%20I%20--%3E%20M%0A%20%20L%20--%3E%20M%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=s('<h2 id="领域地图" tabindex="-1">领域地图 <a class="header-anchor" href="#领域地图" aria-label="Permalink to &quot;领域地图&quot;">​</a></h2><ul><li><strong>研究机构</strong>：Berkeley 的逻辑综合与开源设计生态、清华、复旦、香港中文大学等机构的相关团队，可作为综合、物理设计和可制造性研究的检索入口。</li><li><strong>产业参照</strong>：Cadence、Synopsys、Siemens EDA 提供不同环节的工业工具；制造企业的工艺与设计规则又决定工具需要解决的约束。这不是上科大合作关系清单。</li><li><strong>会议与期刊</strong>：DAC、ICCAD、ASP-DAC、DATE；IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems（TCAD）、ACM Transactions on Design Automation of Electronic Systems（TODAES）。</li></ul><p>AI4EDA 尤其要防止数据泄漏和不公平比较：训练与测试是否来自同一设计的相似切片？对手方法是否有同等调参预算？最终指标是模型预测误差，还是经过真实工具评估的设计质量？论文应明确回答这些问题。</p><h2 id="入门资源" tabindex="-1">入门资源 <a class="header-anchor" href="#入门资源" aria-label="Permalink to &quot;入门资源&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/learning/eda/resources">EDA 算法自学</a> 与 <a href="/shanghaitech-ic-wiki-dev.github.io/learning/eda/">EDA 学习地图</a>：组织图算法、优化和学习方法。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/tools/open-source/">开源 EDA</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/tools/eda/commercial">商业 EDA</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/tools/development/">环境配置</a>：认识工具的适用边界与授权要求。</li><li><a href="https://theopenroadproject.org/" target="_blank" rel="noreferrer">OpenROAD</a>：开源数字物理实现流程入口。</li><li><a href="https://yosyshq.net/yosys/" target="_blank" rel="noreferrer">Yosys</a>：逻辑综合工具与文档。</li></ul><p>起步可以在小型公开设计上选择一个单独任务，先复现基线和约束，再做局部改进。保持设计、库、工具版本和随机种子可追溯，记录运行时间与失败案例，而不只展示最好的结果。</p><h2 id="社区经验征集" tabindex="-1">社区经验征集 <a class="header-anchor" href="#社区经验征集" aria-label="Permalink to &quot;社区经验征集&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">征集</p><p>欢迎该方向课题组同学通过 <a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a> 补充“组里在做什么”、公开数据与工具入门路径、进组准备建议；不提交商业工具许可证、受限 PDK、工艺参数或未公开设计。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://sist.shanghaitech.edu.cn/genghao/main.htm" target="_blank" rel="noreferrer">耿浩学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/zxy1/main.htm" target="_blank" rel="noreferrer">张芯韵学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/zhoupq/main.htm" target="_blank" rel="noreferrer">周平强学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/rxl/main.htm" target="_blank" rel="noreferrer">任轩乐学院主页</a>、<a href="https://sist.shanghaitech.edu.cn/wutao/main.htm" target="_blank" rel="noreferrer">吴涛学院主页</a>。</li><li><a href="https://sist.shanghaitech.edu.cn/_upload/article/files/d0/82/218152ad4bd29c54d8a89d0e6be7/2cba84cd-d335-4a72-8f17-68175bed8e69.pdf" target="_blank" rel="noreferrer">后摩尔中心介绍材料</a>：约 2024 年 DSE、计算光刻与 AI4IC 方向介绍。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">2026–2027 学年 SIST 开课计划</a>：EE215A、SI365 等课程的计划信息，实际以教务系统为准。</li></ul>',10))])}const S=h(u,[["render",D]]);export{_ as __pageData,S as default};
